class Solution:
    def longestPalindrome(self, s: str) -> str:
        if not s:
            return ""
        start, end = 0, 0

        def expand(l, r):
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            return l + 1, r - 1        # 收敛到合法回文边界

        for i in range(len(s)):
            l1, r1 = expand(i, i)      # 奇数长度中心
            if r1 - l1 > end - start:
                start, end = l1, r1
            l2, r2 = expand(i, i + 1)  # 偶数长度中心
            if r2 - l2 > end - start:
                start, end = l2, r2
        return s[start:end + 1]

